func tenantForm() templ.ComponentScript {
	return templ.ComponentScript{
		Name: `__templ_tenantForm_a8b6`,
		Function: `function __templ_tenantForm_a8b6(){return {
		formData: {},
		isDirty: false,
		isSubmitting: false,
		
		init() {
			this.initializeFormData();
			this.watchForChanges();
		},
		
		initializeFormData() {
			const form = this.$refs.form;
			if (form) {
				const formData = new FormData(form);
				this.formData = Object.fromEntries(formData.entries());
			}
		},
		
		watchForChanges() {
			this.$refs.form.addEventListener('input', () => {
				this.isDirty = true;
			});
		},
		
		submitForm() {
			this.isSubmitting = true;
			// Form submission is handled by HTMX
		},
		
		cancelForm() {
			if (this.isDirty) {
				if (confirm('You have unsaved changes. Are you sure you want to cancel?')) {
					this.closeModal();
				}
			} else {
				this.closeModal();
			}
		},
		
		closeModal() {
			// Close modal by clearing container
			document.getElementById('modal-container').innerHTML = '';
		},
		
		saveDraft() {
			// Implement draft saving
			console.log('Save draft');
		}
	}
}`,
		Call:       templ.SafeScript(`__templ_tenantForm_a8b6`),
		CallInline: templ.SafeScriptInline(`__templ_tenantForm_a8b6`),
	}
}

